import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
const t = key => app.translator.trans('ernestdefoe-espn-cfb-ticker.admin.settings.' + key);
const split = value => String(value || '').split(',').map(s => s.trim()).filter(Boolean);
const flip = (list, key, on) => (on ? [...new Set([...list, key])] : list.filter(k => k !== key)).join(',');

/** Which ESPN scoreboards the bar shows, as tick boxes over one comma-joined setting. */
export default class LeaguePicker extends Component {
  view() {
    // From the server's list (extend.php), never a copy written here.
    const leagues = app.data.espnTickerLeagues || [];
    const ranked = app.data.espnTickerRanked || [];
    const chosen = split(this.attrs.value());
    const top25 = split(this.attrs.top25());
    return m('.Form-group.CfbTickerLeagues', [m('label', t('leagues_label')), m('.helpText', t('leagues_help')), leagues.map(key => m('.CfbTickerLeagues-item', {
      key
    }, [m('label.checkbox', [m('input[type=checkbox]', {
      checked: chosen.includes(key),
      onchange: e => this.attrs.value(flip(chosen, key, e.target.checked))
    }), t('league.' + key)]),
    // Offered once the league is ticked: a full college day is well
    // over a hundred games.
    ranked.includes(key) && chosen.includes(key) ? m('label.checkbox.CfbTickerLeagues-top25', [m('input[type=checkbox]', {
      checked: top25.includes(key),
      onchange: e => this.attrs.top25(flip(top25, key, e.target.checked))
    }), t('top25_label')]) : null]))]);
  }
}
flarum.reg.add('ernestdefoe-espn-cfb-ticker', 'admin/components/LeaguePicker', LeaguePicker);